let step3CatalogController;
function step3Catalog(){
  return step3CatalogController ||= createStep3ModelCatalog({
    select:$('#model'),analysisSelect:$('#analyzeModel'),status:$('#step3CatalogStatus'),
    readConfig:()=>{
      const provider=$('#provider').value,c=cfg(),base=baseURL();
      return {provider,base,key:cleanKey($('#key').value),proto:c.proto,mode,
        chat:c.chat||[],image:c.image||[],vision:c.vision||[],
        snapshotAllowed:provider==='nonelinear'&&base===(MAN.providers.nonelinear.base||'').replace(/\/+$/,'')};
    },
    readSaved:(p,analysis)=>localStorage.getItem((analysis?'ff_amodel_':'ff_model_')+p),
    kindOf,isVisualModel:isVisualChatModel,
    onLiveModels:list=>{liveModels.model=list;checkModelEnabled('#model','#modelWarn',list);},
    onRender:()=>syncImageRatioSupport()
  });
}
async function populateModels(){
  // Step 3 owns its discovery/display. Keep Step 4's original request and guard.
  const p = $('#provider').value;
  const wanted = mode==='svg' ? 'chat' : 'image';
  const requestBase=baseURL(), requestKey=cleanKey($('#key').value);
  const step3=step3Catalog().refresh();
  const res = await fetchOnlineModels();
  if(p!==$('#provider').value || requestBase!==baseURL() || requestKey!==cleanKey($('#key').value) || wanted!==(mode==='svg'?'chat':'image')) return;
  populateReconstructionModels(res);
  await step3;
}

