async function populateAnalyzeModels(){
  const c=cfg(), s=$('#analyzeModel'); s.innerHTML='';
  if(c.vision.length){ const g=optgroup(tt('og.amodel')); c.vision.forEach(m=>g.appendChild(option(m))); s.appendChild(g); }
  const requestBase=baseURL(), requestKey=cleanKey($('#key').value), requestProvider=$('#provider').value;
  const res = await fetchOnlineModels();
  if(requestProvider!==$('#provider').value || requestBase!==baseURL() || requestKey!==cleanKey($('#key').value)) return;
  const vis = res.list.filter(m=>isVisualChatModel(m,c.vision));
  if(vis.length){ const g=optgroup(tt('og.live')); [...new Set(vis)].forEach(m=>g.appendChild(option(m))); s.appendChild(g); }
  else if(key_present() && !res.ok && !c.vision.length){
    const g=optgroup(tt('og.nolive'));
    const o=option(tt('og.hosted')); o.disabled=true; g.appendChild(o); s.appendChild(g);
  }
  const saved = localStorage.getItem('ff_amodel_'+$('#provider').value);
  if(saved && [...s.options].some(o=>o.value===saved)) s.value=saved;
}
